document.querySelector('#failed').insertAdjacentHTML('afterend',`<section class="view" id="audit"><div class="cards audit-cards"><div class="stat"><span>Eventos consultados</span><strong id="auditEvents">0</strong></div><div class="stat"><span>Procesos concluidos</span><strong id="auditCompleted">0</strong></div><div class="stat"><span>Tiempo promedio</span><strong id="auditAverage">--</strong></div></div><div class="panel"><div class="toolbar audit-toolbar"><input id="auditSearch" placeholder="Buscar folio, empresa, colaborador o usuario"><select id="auditEvent"><option value="">Todas las acciones</option></select><input id="auditFrom" type="date"><input id="auditTo" type="date"><span></span><button class="secondary" type="button" onclick="clearAuditFilters()">Limpiar</button></div><div class="audit-note">La bitácora conserva quién realizó cada acción, el objeto afectado, fecha, IP y cambios operativos. No incluye contraseñas, firmas ni imágenes.</div><div class="table-wrap"><table><thead><tr><th>Fecha y hora</th><th>Actor</th><th>Acción</th><th>Empresa / colaborador</th><th>Folio</th><th>Detalle</th></tr></thead><tbody id="auditRows"></tbody></table></div></div><div class="panel" style="margin-top:18px"><h3 style="margin-top:0">Tiempos del proceso</h3><p class="audit-note">Tiempo desde el alta hasta que la constancia queda disponible. Los eventos empezarán a medirse desde la activación de esta auditoría.</p><div class="table-wrap"><table><thead><tr><th>Folio</th><th>Colaborador</th><th>Empresa</th><th>Alta</th><th>Carta</th><th>Video</th><th>Examen</th><th>Constancia lista</th><th>Tiempo total</th></tr></thead><tbody id="auditKpiRows"></tbody></table></div></div></section>`);
