function auditDate(value){return value?new Date(value).toLocaleString('es-MX',{dateStyle:'short',timeStyle:'short'}):'--'}
function auditDuration(start,end){if(!start||!end)return'--';const hours=(new Date(end)-new Date(start))/3600000;return hours<24?`${hours.toFixed(1)} h`:`${(hours/24).toFixed(1)} días`}
function renderAudit(){const summary=auditData.summary||{};document.getElementById('auditEvents').textContent=summary.eventos||0;document.getElementById('auditCompleted').textContent=summary.procesosConcluidos||0;document.getElementById('auditAverage').textContent=summary.tiempoPromedioHoras==null?'--':`${summary.tiempoPromedioHoras} h`;document.getElementById('auditRows').innerHTML=(auditData.events||[]).map(event=>`<tr><td>${auditDate(event.creado_en)}</td><td><span class="audit-actor">${esc(event.actor_nombre)}</span><br><small>${esc(event.actor_tipo)}</small></td><td><span class="audit-action">${esc(String(event.evento||'').replaceAll('_',' '))}</span></td><td>${esc(event.empresa||'--')}<br><small>${esc(event.colaborador||'')}</small></td><td class="token-code">${esc(event.folio||'--')}</td><td class="audit-detail">${esc(event.detalle||'--')}</td></tr>`).join('')||'<tr><td colspan="6" class="audit-kpi-empty">No hay eventos con los filtros seleccionados.</td></tr>';document.getElementById('auditKpiRows').innerHTML=(auditData.kpis||[]).map(k=>`<tr><td class="token-code">${esc(k.folio)}</td><td>${esc(k.colaborador||'--')}</td><td>${esc(k.empresa||'--')}</td><td>${auditDate(k.alta_en)}</td><td>${auditDate(k.carta_en)}</td><td>${auditDate(k.video_en)}</td><td>${auditDate(k.examen_en)}</td><td>${auditDate(k.constancia_lista_en)}</td><td><strong>${auditDuration(k.alta_en,k.constancia_lista_en)}</strong></td></tr>`).join('')||'<tr><td colspan="9" class="audit-kpi-empty">Aún no hay recorridos medibles.</td></tr>'}
async function loadAudit(){const params=new URLSearchParams();const q=document.getElementById('auditSearch')?.value.trim(),event=document.getElementById('auditEvent')?.value,from=document.getElementById('auditFrom')?.value,to=document.getElementById('auditTo')?.value;if(q)params.set('q',q);if(event)params.set('evento',event);if(from)params.set('desde',from);if(to)params.set('hasta',to);const response=await fetch('/admin-auditoria?'+params,{headers:{Authorization:'Bearer '+token}}),payload=await response.json().catch(()=>({}));if(!response.ok||!payload.ok)return Swal.fire('Auditoría no disponible',payload.error||'No fue posible cargar la bitácora','error');auditData=payload;const select=document.getElementById('auditEvent'),selected=event||'';select.innerHTML='<option value="">Todas las acciones</option>'+payload.eventTypes.map(item=>`<option value="${esc(item.evento)}">${esc(item.evento.replaceAll('_',' '))} (${item.total})</option>`).join('');select.value=selected;renderAudit()}
