renderAudit=function(){const summary=auditData.summary||{},pagination=auditData.pagination||{};document.getElementById('auditEvents').textContent=summary.eventos||0;document.getElementById('auditCompleted').textContent=summary.procesosConcluidos||0;document.getElementById('auditAverage').textContent=summary.tiempoPromedioHoras==null?'--':`${summary.tiempoPromedioHoras} h`;document.getElementById('auditRows').innerHTML=(auditData.events||[]).map(event=>`<tr><td>${auditDate(event.creado_en)}</td><td><span class="audit-actor">${esc(event.actor_nombre)}</span><br><small>${esc(event.actor_tipo)}</small></td><td><span class="audit-action">${esc(String(event.evento||'').replaceAll('_',' '))}</span></td><td>${esc(event.empresa||'--')}<br><small>${esc(event.colaborador||'')}</small></td><td class="token-code">${esc(event.folio||'--')}</td><td class="audit-detail">${esc(event.detalle||'--')}</td></tr>`).join('')||'<tr><td colspan="6" class="audit-kpi-empty">No hay eventos con los filtros seleccionados.</td></tr>';document.getElementById('auditKpiRows').innerHTML=(auditData.kpis||[]).map(k=>`<tr><td class="token-code">${esc(k.folio)}</td><td>${esc(k.colaborador||'--')}</td><td>${esc(k.empresa||'--')}</td><td>${auditDate(k.alta_en)}</td><td>${auditDate(k.sesion_en)}<br><small>${auditDuration(k.alta_en,k.sesion_en)}</small></td><td>${auditDate(k.carta_en)}</td><td>${auditDate(k.video_en)}<br><small>${auditDuration(k.curso_inicio_en,k.video_en)}</small></td><td>${auditDate(k.examen_en)}<br><small>${auditDuration(k.examen_inicio_en,k.examen_en)}</small></td><td>${auditDate(k.constancia_lista_en)}</td><td><strong>${auditDuration(k.alta_en,k.constancia_lista_en)}</strong></td></tr>`).join('')||'<tr><td colspan="10" class="audit-kpi-empty">Aún no hay recorridos medibles.</td></tr>';document.getElementById('auditCompanyRows').innerHTML=(auditData.companyKpis||[]).map(company=>`<tr><td><strong>${esc(company.nombre)}</strong></td><td>${auditDate(company.token_emitido_en)}</td><td>${auditDate(company.empresa_registrada_en)}</td><td>${auditDate(company.primer_colaborador_en)}</td><td><strong>${auditCompanyDuration(company.token_emitido_en,company.primer_colaborador_en)}</strong></td><td>${company.colaboradores||0}</td><td>${company.concluidos||0}</td><td><strong>${company.promedio_constancia_horas==null?'--':Number(company.promedio_constancia_horas).toFixed(1)+' h'}</strong></td></tr>`).join('')||'<tr><td colspan="8" class="audit-kpi-empty">No hay empresas para el filtro seleccionado.</td></tr>';auditPageControls('auditEventPages',pagination.totalEvents,'Eventos');auditPageControls('auditKpiPages',pagination.totalKpis,'Procesos')};
loadAudit=async function(){const params=new URLSearchParams(),q=document.getElementById('auditSearch')?.value.trim(),event=document.getElementById('auditEvent')?.value,companyId=document.getElementById('auditCompany')?.value,from=document.getElementById('auditFrom')?.value,to=document.getElementById('auditTo')?.value;if(q)params.set('q',q);if(event)params.set('evento',event);if(companyId)params.set('empresaId',companyId);if(from)params.set('desde',from);if(to)params.set('hasta',to);params.set('page',auditPage);const response=await fetch('/admin-auditoria?'+params,{headers:{Authorization:'Bearer '+token}}),payload=await response.json().catch(()=>({}));if(!response.ok||!payload.ok)return Swal.fire('Auditoría no disponible',payload.error||'No fue posible cargar la bitácora','error');auditData=payload;const eventSelect=document.getElementById('auditEvent'),companySelect=document.getElementById('auditCompany'),selectedEvent=event||'',selectedCompany=companyId||'';eventSelect.innerHTML='<option value="">Todas las acciones</option>'+payload.eventTypes.map(item=>`<option value="${esc(item.evento)}">${esc(item.evento.replaceAll('_',' '))} (${item.total})</option>`).join('');eventSelect.value=selectedEvent;const companies=(data.companies||[]).filter(company=>company.empresa_id).map(company=>({id:company.empresa_id,nombre:company.nombre||company.empresa_autorizada}));companySelect.innerHTML='<option value="">Todas las empresas</option>'+[...new Map(companies.map(company=>[company.id,company])).values()].map(company=>`<option value="${Number(company.id)}">${esc(company.nombre)}</option>`).join('');companySelect.value=selectedCompany;renderAudit()};
