function parseQuestionCsv(text){const rows=[],row=[],value=[];let quoted=false;for(let i=0;i<text.length;i++){const char=text[i],next=text[i+1];if(char==='"'&&quoted&&next==='"'){value.push('"');i++}else if(char==='"'){quoted=!quoted}else if(char===','&&!quoted){row.push(value.join('').trim());value.length=0}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&next==='\n')i++;row.push(value.join('').trim());value.length=0;if(row.some(cell=>cell!==''))rows.push(row.splice(0));else row.length=0}else value.push(char)}row.push(value.join('').trim());if(row.some(cell=>cell!==''))rows.push(row);if(rows.length<2)throw new Error('El archivo debe incluir encabezados y al menos una pregunta');const headers=rows.shift().map(header=>header.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().replace(/\s+/g,'_'));return rows.map(cells=>Object.fromEntries(headers.map((header,index)=>[header,cells[index]||''])))}
