document.head.insertAdjacentHTML('beforeend',`<style>.physical-header{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:20px}.physical-header h2{margin:0}.physical-header p,.physical-note{color:#93a4ba;font-size:13px}.physical-cards{display:grid;grid-template-columns:repeat(3,minmax(160px,1fr));gap:14px;margin-bottom:20px}.physical-note{background:#0a1422;border:1px solid #263449;border-radius:9px;padding:11px 13px;margin-bottom:16px}.physical-actions{white-space:nowrap}.physical-actions button{margin:2px}.camera-preview{width:100%;max-height:360px;background:#050c17;border:1px solid #263449;border-radius:12px;object-fit:cover}.camera-note{font-size:12px;color:#93a4ba;margin-top:9px}@media(max-width:650px){.physical-header{flex-direction:column}.physical-cards{grid-template-columns:1fr}}</style>`);
const physicalNav=document.querySelector('[data-view="physical"]');
function physicalDuration(value){if(!value)return'--';const hours=Math.max(0,(Date.now()-new Date(value).getTime())/3600000);return hours<24?`${hours.toFixed(1)} h`:`${(hours/24).toFixed(1)} días`}
function physicalBadge(status){return badge(status==='PENDIENTE_LLEGADA'?'PENDIENTE':status==='EN_SITIO'?'EN SITIO':status==='EN_ATENCION'?'EN ATENCIÓN':'CONCLUIDO')}
function renderPhysicalQueue(){const summary=physicalQueue.summary||{},queue=physicalQueue.queue||[];document.getElementById('physicalPending').textContent=summary.pendientesLlegada||0;document.getElementById('physicalOnsite').textContent=summary.enSitio||0;document.getElementById('physicalService').textContent=summary.enAtencion||0;document.getElementById('physicalRows').innerHTML=queue.map(item=>{const done=!!item.atendido_en,onsite=!!item.llegada_en;let action=done?'<small>Concluido</small>':!onsite?`<button class="secondary" onclick="registerPhysicalArrival(${Number(item.user_id)})">Registrar llegada</button>`:`<button class="primary" onclick="openPhysicalCamera(${Number(item.user_id)},'${esc(item.folio)}','${esc(item.name)}')">Tomar fotografía</button>`;return `<tr><td>${auditDate(item.solicitado_en)}</td><td>${auditDate(item.llegada_en)}</td><td class="token-code">${esc(item.folio)}</td><td><strong>${esc(item.name)}</strong></td><td>${esc(item.empresa)}</td><td>${physicalBadge(item.estado)}</td><td><strong>${done?'--':physicalDuration(item.llegada_en||item.solicitado_en)}</strong></td><td class="physical-actions">${action}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No hay registros de toma física.</td></tr>'}
async function loadPhysicalQueue(){const response=await fetch('/admin-toma-fisica',{headers:{Authorization:'Bearer '+token}}),payload=await response.json().catch(()=>({}));if(!response.ok||!payload.ok)return Swal.fire('Cola no disponible',payload.error||'No fue posible consultar la cola','error');physicalQueue=payload;renderPhysicalQueue()}
async function registerPhysicalArrival(userId){const response=await fetch(`/admin-toma-fisica/${userId}/llegada`,{method:'POST',headers:{Authorization:'Bearer '+token}}),payload=await response.json().catch(()=>({}));if(!response.ok||!payload.ok)return Swal.fire('Error',payload.error||'No fue posible registrar la llegada','error');await loadPhysicalQueue();Swal.fire({icon:'success',title:payload.already?'Llegada ya registrada':'Llegada registrada',timer:1300,showConfirmButton:false})}
async function openPhysicalCamera(userId,folio,nombre){const start=await fetch(`/admin-toma-fisica/${userId}/iniciar`,{method:'POST',headers:{Authorization:'Bearer '+token}}),startData=await start.json().catch(()=>({}));if(!start.ok||!startData.ok)return Swal.fire('No es posible atender',startData.error||'No fue posible iniciar la atención','error');let stream;const result=await Swal.fire({title:'Fotografía física',width:680,html:`<div style="text-align:left"><p><strong>${esc(nombre)}</strong><br><small>${esc(folio)}</small></p><video id="physicalCamera" class="camera-preview" autoplay playsinline muted></video><p class="camera-note">Verifica que el rostro sea visible antes de capturar. Al aceptar se concluye la toma física y se detiene el tiempo de atención.</p></div>`,showCancelButton:true,confirmButtonText:'Capturar y aceptar fotografía',cancelButtonText:'Cancelar',buttonsStyling:false,customClass:{popup:'tia-modal',confirmButton:'tia-primary',cancelButton:'tia-secondary'},didOpen:async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:1280},height:{ideal:720}},audio:false});document.getElementById('physicalCamera').srcObject=stream}catch(error){Swal.showValidationMessage('No fue posible acceder a la cámara. Verifica permisos y vuelve a intentar.')}},preConfirm:async()=>{const video=document.getElementById('physicalCamera');if(!video?.videoWidth){Swal.showValidationMessage('La cámara aún no está lista');return false}const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9));if(!blob){Swal.showValidationMessage('No fue posible capturar la fotografía');return false}const form=new FormData();form.append('photo',blob,'toma-fisica.jpg');const response=await fetch(`/admin-toma-fisica/${userId}/fotografia`,{method:'POST',headers:{Authorization:'Bearer '+token},body:form}),payload=await response.json().catch(()=>({}));if(!response.ok||!payload.ok){Swal.showValidationMessage(payload.error||'No fue posible guardar la fotografía');return false}return true},willClose:()=>{stream?.getTracks().forEach(track=>track.stop())}});if(result.isConfirmed){await loadPhysicalQueue();Swal.fire({icon:'success',title:'Toma física concluida',text:'La fotografía fue aceptada y el tiempo de atención quedó registrado.',timer:1800,showConfirmButton:false})}}
function copyKioskUrl(){const url=`${location.origin}/registro-llegada.html`;navigator.clipboard?.writeText(url);Swal.fire({icon:'success',title:'Enlace copiado',text:url,timer:1800,showConfirmButton:false})}
physicalNav.onclick=async()=>{document.querySelectorAll('.nav button').forEach(item=>item.classList.remove('active'));physicalNav.classList.add('active');activeView='physical';document.querySelectorAll('.view').forEach(view=>view.classList.toggle('active',view.id==='physical'));document.getElementById('title').textContent='Toma física TIA';document.getElementById('subtitle').textContent='Recepción, atención y cierre auditable de fotografías presenciales';await loadPhysicalQueue()};
(async()=>{const response=await fetch('/admin-overview',{headers:{Authorization:'Bearer '+token}});if(!response.ok)return;const overview=await response.json();physicalNav.style.display=overview.admin?'':'none'})();
